import{_ as a,o as t,c as i,a4 as n}from"./chunks/framework.BRzJ4ijD.js";const c=JSON.parse('{"title":"以太网帧、CSMA/CD、PHY/MAC","description":"","frontmatter":{},"headers":[],"relativePath":"networking/phy/ethernet.md","filePath":"networking/phy/ethernet.md","lastUpdated":1788475713000}'),e={name:"networking/phy/ethernet.md"};function l(p,s,r,h,d,o){return t(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="以太网帧、csma-cd、phy-mac" tabindex="-1">以太网帧、CSMA/CD、PHY/MAC <a class="header-anchor" href="#以太网帧、csma-cd、phy-mac" aria-label="Permalink to &quot;以太网帧、CSMA/CD、PHY/MAC&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>深入拆 802.3 以太网：帧格式每一段为什么这么贴、CSMA/CD 算法细节、PHY 与 MAC 芯片实际怎么分块、为什么 100M 时代叫 MII、1000M 叫 GMII、10G 叫 XGMII——名字背后真实都是 IEEE 802.3 clause 的硬件 IP 切分边界。</p><h2 id="思维链" tabindex="-1">思维链 <a class="header-anchor" href="#思维链" aria-label="Permalink to &quot;思维链&quot;">​</a></h2><p>应用层以为 <code>Ethernet</code> 是个抽象概念，但<strong>每个开关 + 编码 + 物理标准都是真实硬件</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的 sysctl 设 MTU=1500 → 内核 skb data 大小 = 1514 (含 MAC header)</span></span>
<span class="line"><span>   -&gt; 网卡驱动 prep 渲染页 + pre-pad VLAN tag + 加 EtherType</span></span>
<span class="line"><span>   -&gt; MAC 重新组帧：Preamble(7) + SFD(1) + Header(14) + Payload(1500) + FCS(4)</span></span>
<span class="line"><span>   -&gt; PCS 编 64b/66b + 扰码</span></span>
<span class="line"><span>   -&gt; PMA 串并转换并把 8 通道并行 (10G) 转换成 4 通道 25Gbps serdes</span></span>
<span class="line"><span>   -&gt; PMD 把 25Gbps 电信号变光（laser driver）打向光纤</span></span></code></pre></div><p>每个步骤背后都是 IEEE 802.3 标准的某个 clause + 各厂商芯片 IP。每个 PorV/Vendor 自己的 SDK 大小写参数都没调好就是出工程师连夜加班的根因。</p><h2 id="帧格式的每一字节" tabindex="-1">帧格式的每一字节 <a class="header-anchor" href="#帧格式的每一字节" aria-label="Permalink to &quot;帧格式的每一字节&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    7        1         6        6        2       46-1500      4      12</span></span>
<span class="line"><span>+---------+---------+-------+--------+--------+-----------+-------+------+</span></span>
<span class="line"><span>|Preamble | SFD     |  DA    |   SA    | EtherType|  Payload   |  FCS  | IFG  |</span></span>
<span class="line"><span>|10101010×|10101011 |48bit MAC| 48bit   | 16 bit  |  上层协议  |CRC-32 | 9.6 µs|</span></span>
<span class="line"><span>|   7     |         |        |        |         |            |       |(Gbps用减少到1B) |</span></span>
<span class="line"><span>+---------+---------+-------+--------+--------+-----------+-------+------+</span></span></code></pre></div><ul><li><strong>Preamble 7 字节</strong>：收端时钟恢复用，让 PLL 锁定相位。共享介质时代所有节点靠这 7 字节&quot;时基对齐&quot;。10G 全双工后理论上 Preamble 可省，但所有以太网帧都保留作兼容。</li><li><strong>SFD 1 字节</strong>：<code>10101011</code> 标记帧起点（与 Preamble 的最后一位相反）。</li><li><strong>DA/SA</strong>：MAC 地址 6 字节，前 24 bit 是 IEEE OUI（厂商代码），后 24 bit 厂商自分配。<code>FF:FF:FF:FF:FF:FF</code> 是广播、首字节 bit0=1 是组播。</li><li><strong>EtherType</strong>：&lt; 1536 是 length（802.3 raw 格式，几乎绝迹），≥ 1536 标识上层（0x0800 IPv4, 0x86dd IPv6, 0x0806 ARP, 0x88cc LLDP, 0x8906 RoCEv2, 0x8915 NSH）。</li><li><strong>Payload 46-1500</strong>：&lt; 46 字节要 padding 凑 64 字节最小帧。</li><li><strong>FCS 4 字节</strong>：CRC-32 多项式 <code>0x04C11DB7</code>。</li><li><strong>IFG 12 字节</strong>：帧间间隔（9.6 µs @10M，1.2 µs @1G），10G+ 可缩到 0.096 µs（1 字节时间）。这是物理层强制间隔，给收端腾出&quot;处理一帧&quot;的时间。</li></ul><h3 id="巨型帧-jumbo-frame" tabindex="-1">巨型帧（Jumbo Frame） <a class="header-anchor" href="#巨型帧-jumbo-frame" aria-label="Permalink to &quot;巨型帧（Jumbo Frame）&quot;">​</a></h3><p>9000 字节 payload 用于 SAN / 大数据 Shuffle / RoCE：</p><ul><li>1500 MTU: 4 KB 文件 = 2.7 个包 → 协议头开销 18/1518 ≈ <strong>1.19%</strong></li><li>9000 MTU: 4 KB 文件 = 0.45 个包 → 协议头开销 18/9018 ≈ <strong>0.20%</strong></li><li>减少 NIC 中断 → CPU 占用降 30-50%</li><li>Spark / Flink 网络洗牌用 jumbo 后 CPU 利用率有 10-20% 的下降</li></ul><p>但跨互联网必须 PMTUD 路径发现，否则 jumbo 在普通路由器上触发分片丢包。<strong>AWS 内 VPC</strong>、Azure 内、自建数据中心可以全部 9000；跨云不要用。</p><hr><h2 id="csma-cd-完整算法" tabindex="-1">CSMA/CD 完整算法 <a class="header-anchor" href="#csma-cd-完整算法" aria-label="Permalink to &quot;CSMA/CD 完整算法&quot;">​</a></h2><p>发送：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 监听介质 (carrier sense)，忙 -&gt; 等待空闲</span></span>
<span class="line"><span>2. 开始发送</span></span>
<span class="line"><span>3. 边发边听：</span></span>
<span class="line"><span>   - 检测到冲突 -&gt; 立即停止 -&gt; 发 32 bit jam signal</span></span>
<span class="line"><span>   - -&gt; 二进制指数退避</span></span>
<span class="line"><span>4. 退避次数 K &lt;- min(10, retry_count)</span></span>
<span class="line"><span>   - backoff_time = random() % (2^K) × slot_time</span></span>
<span class="line"><span>   - 10 Mbps slot_time = 51.2 µs (512 bit 时间)</span></span>
<span class="line"><span>5. 16 次失败 -&gt; 抛弃帧</span></span></code></pre></div><p>为什么退避最大 10 而不是更大？2^10 × 51.2 µs = 26 ms 已经远超冲突窗口，再大无意义。</p><h3 id="全双工模式" tabindex="-1">全双工模式 <a class="header-anchor" href="#全双工模式" aria-label="Permalink to &quot;全双工模式&quot;">​</a></h3><p>交换机的每端口是点对点链路，无共享介质、无冲突检测。所以 CSMA/CD 实际不启用。<strong>半双工（同轴 / Hub）才用得上</strong>。所有现代以太网都是全双工。</p><hr><h2 id="mac-体系" tabindex="-1">MAC 体系 <a class="header-anchor" href="#mac-体系" aria-label="Permalink to &quot;MAC 体系&quot;">​</a></h2><h3 id="mii-gmii-xgmii-接口速率" tabindex="-1">MII / GMII / XGMII 接口速率 <a class="header-anchor" href="#mii-gmii-xgmii-接口速率" aria-label="Permalink to &quot;MII / GMII / XGMII 接口速率&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名字</th><th>数据宽度</th><th>时钟</th><th>总线带宽</th><th>用途</th></tr></thead><tbody><tr><td>MII</td><td>4 bit</td><td>2.5 MHz</td><td>100 Mbps</td><td>100BASE-TX</td></tr><tr><td>GMII</td><td>8 bit</td><td>125 MHz</td><td>1000 Mbps</td><td>1000BASE-T</td></tr><tr><td>RGMII</td><td>4 bit DDR</td><td>125 MHz</td><td>1000 Mbps</td><td>板内 1G</td></tr><tr><td>XGMII</td><td>32 bit</td><td>156.25 MHz</td><td>10 Gbps</td><td>10GBASE-*</td></tr><tr><td>XLAUI</td><td>4×10g serdes</td><td>—</td><td>40 Gbps</td><td>40GBASE-R</td></tr><tr><td>CAUI</td><td>10×10g serdes</td><td>—</td><td>100 Gbps</td><td>100GBASE-CR4</td></tr><tr><td>XFI</td><td>1×10g serdes</td><td>—</td><td>10 Gbps</td><td>10GBASE-SR/LR</td></tr></tbody></table><p>每个都以 8b/10b 或 64b/66b 编码传输。MAC 与 PHY 之间的片内总线 → 这些 MII/XGMII 的存在是为了让 MAC vendor 和 PHY vendor 可以独立 IP 授权，让 ASIC 集成度可以增长。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>名字里的 X/XG/S/X/SR/LR 这些前缀其实就是 IEEE 802.3 clause 编号区分：</p><ul><li><strong>X</strong> = 10G</li><li><strong>S</strong> = Short Reach (&lt;100m, 多模)</li><li><strong>L</strong> = Long Reach (&lt;10km, 单模)</li><li><strong>R</strong> = Extended Reach</li><li><strong>CR</strong> = Copper (直连铜)</li></ul></div><hr><h2 id="phy-内部-千万级门电路" tabindex="-1">PHY 内部：千万级门电路 <a class="header-anchor" href="#phy-内部-千万级门电路" aria-label="Permalink to &quot;PHY 内部：千万级门电路&quot;">​</a></h2><p>10GBASE-KR PHY 内部数字部分：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MAC 8B  ||  TX_PMA  &lt;-  TX_PCS  &lt;-  64b/66b enc  &lt;-  GMII</span></span>
<span class="line"><span>      ||                                ↑</span></span>
<span class="line"><span>      ||                            scramble + LDPC/BCH</span></span>
<span class="line"><span>MKD ||  RX_PMA   -&gt;  RX_PCS  -&gt;  64b/66b dec  -&gt;  GMII</span></span></code></pre></div><ul><li><strong>PCS</strong>: 64b/66b 编码 + Lane skew 对齐（多 lane）/ FEC</li><li><strong>PMA</strong>: 串并转换 + CDR (Clock Data Recovery)</li><li><strong>PMD</strong>: 激光驱动 / 铜驱动</li></ul><h3 id="auto-negotiation-与-fec" tabindex="-1">Auto-Negotiation 与 FEC <a class="header-anchor" href="#auto-negotiation-与-fec" aria-label="Permalink to &quot;Auto-Negotiation 与 FEC&quot;">​</a></h3><p>10G、25G 等速率需要 RS-FEC（528/514 子编码）来纠正 BER 让光模块尺寸可以缩到 1U：</p><ul><li>25G Base-R: FEC on/off 由 link partner 能力决定</li><li>25G RS-FEC: 528 symbol 中 514 信息 + 14 校验 → BER 1e-5 → 1e-12</li></ul><p>启动时 AN 协商 FEC on/off，开 FEC 多 4%-5% 带宽开销但能纠错，关 FEC 反之。</p><hr><h2 id="crc-32-检错不是签名" tabindex="-1">CRC-32 检错不是签名 <a class="header-anchor" href="#crc-32-检错不是签名" aria-label="Permalink to &quot;CRC-32 检错不是签名&quot;">​</a></h2><p>FCS 是 CRC-32 IEEE 802.3：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> crc32_eth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(data):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    crc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">FFFFFFFF</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> data:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        crc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">^=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> _ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            crc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (crc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">^</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">04C11DB7</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> crc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80000000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> else</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            crc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">FFFFFFFF</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> crc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">^</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">FFFFFFFF</span></span></code></pre></div><ul><li>能检出所有 ≤ 31 bit 突发错（突发错 = 连续 bit 错误）</li><li>能检出双 bit 错（2 bit distance 的多项式构造保证）</li><li>漏检概率 ≈ 2^-32 ≈ 2.3e-10</li><li><strong>不是密码学哈希</strong>：恶意攻击者可构造碰撞 → 所以不能用于完整性校验在已被人工修改的场景</li></ul><p>但实际硬件线上：CRC32 + 距离 ~4 是非常够用了，因为线上 bit flip 来自信道噪声而非攻击者。链路层做到 BER 1e-12，端到端的 TLS MAC（HMAC SHA-256）和 IPsec ESP 才负责&quot;完整性防伪&quot;。</p><hr><h2 id="物理层中的误码-ber" tabindex="-1">物理层中的误码 (BER) <a class="header-anchor" href="#物理层中的误码-ber" aria-label="Permalink to &quot;物理层中的误码 (BER)&quot;">​</a></h2><p>不同介质的典型残留 BER：</p><table tabindex="0"><thead><tr><th>介质</th><th>残留 BER</th></tr></thead><tbody><tr><td>Cat6A 10G</td><td>1e-10 量级</td></tr><tr><td>OM4 多模 100G-DR4</td><td>1e-12 (预计温漂高时变 1e-10)</td></tr><tr><td>单模 100G-ZR 80km</td><td>1e-9 (FEC 关捞回来)</td></tr><tr><td>RoCEv2 PFC 期间</td><td>类似 1e-12</td></tr><tr><td>5G 无线</td><td>1e-6 (高层 HARQ / RLC 重传兜底)</td></tr></tbody></table><p>工业上无线链路与光纤链路 BER 相差 6 个数量级，所以上层重传策略完全不同——这就是为什么 4G/5G 用 HARQ + RLC + PDCP 三层捆绑重传。</p><hr><h2 id="真实生产事故参考" tabindex="-1">真实生产事故参考 <a class="header-anchor" href="#真实生产事故参考" aria-label="Permalink to &quot;真实生产事故参考&quot;">​</a></h2><ol><li><strong>Equinix 2020</strong>：某客户接入 Cisco Nexus 9332 配置一端强制 <code>speed 10000 duplex full</code>，对端 auto → duplex mismatch → 吞吐只有预期 50%、大量 late collision。教训：<strong>所有接入端口启用 auto-negotiation，不要禁用</strong>。</li><li><strong>2019 上海某数据中心</strong>：单一天空调故障后机房内温度从 23°C 升到 65°C → SFP 光模块温度跨越工作点 → 大量 CRC 错误，部分链路自动 down。后续部署温度+光功率联监控（laser bias current + receiving optical power 长期趋势）就能在硬件崩塌前 24h 预警。</li><li><strong>2017 某 IDC jumbo 坑</strong>：所有 ToR-Spine 配 9000 MTU 但有一个机架接入 leaf 误配 1500 → 大包不能转发 → 上层 TCP 重试，最终表现为 MapReduce shuffle 间隔 5-10s 一次的 fixed 延迟峰。<strong>教训</strong>：所有设备厂商默认 MTU 必须配置管理，新机柜上线时先做全路径 ping -M do -s 8972 验证。</li></ol><h2 id="这一章带走的东西" tabindex="-1">这一章带走的东西 <a class="header-anchor" href="#这一章带走的东西" aria-label="Permalink to &quot;这一章带走的东西&quot;">​</a></h2><ol><li>帧每段都是为时钟恢复 / 寻址 / 上层封装 / 检错专门设计；64 字节最小帧是 10 Mbps 下冲突窗口的物理痕迹</li><li>CSMA/CD 退避算法 = 二进制指数 + slot time；现代全双工链路已不使用但保留作兼容</li><li>MII/GMII/XGMII 是 MAC↔PHY 接口分层，只对硬件工程师有意义——名字里的 X/S/L/R 是 IEEE 802.3 clause 的语义</li><li>CRC-32 检错 ≠ 完整性签名，链路层做到 BER 1e-12 后端到端必须用 TLS MAC / IPsec ESP</li><li>巨型帧 9000 在数据中心 5-10% 性能收益，但跨互联网会触发 PMTUD 黑洞</li></ol><p>下一节 → <a href="./optical">光纤、波分复用、机房布线</a></p>`,53)])])}const g=a(e,[["render",l]]);export{c as __pageData,g as default};
